    if(t===35500) lbl="35.5K";
    svg.appendChild(txt(lbl,{x:ml-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
