    svg.appendChild(txt(data[i].d,{x:xp(i),y:H-mb+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
