  var n=data.length;
  var W=680,H=300,ml=62,mr=24,mt=24,mb=46;
  var PW=W-ml-mr, PH=H-mt-mb;
  var minV=58, maxV=125;
  function xp(i){return ml+i*(PW/(n-1));}
  function yp(v){return mt+PH-(v-minV)/(maxV-minV)*PH;}
  function el(tag,attrs){
    var e=document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){var e=el("text",attrs);e.textContent=s;return e;}
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("width","100%");
  svg.style.display="block";
  [60,70,80,90,100,110,120].forEach(function(t){
    var y=yp(t);
    svg.appendChild(el("line",{x1:ml,x2:ml+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt("$"+t,{x:ml-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // x labels every 4 weeks
  for(var i=0;i<n;i+=4){
    svg.appendChild(txt(data[i].w,{x:xp(i),y:H-mb+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  }
  svg.appendChild(txt(data[n-1].w,{x:xp(n-1),y:H-mb+14,"text-anchor":"end","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Event band: conflict surge
  svg.appendChild(el("rect",{x:xp(9),y:mt,width:xp(14)-xp(9),height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(txt("Conflict surge",{x:xp(9)+4,y:mt+14,"font-size":"7","font-weight":"700","fill":"#8a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Pre-conflict reference line at 67
  var refY=yp(67);
  svg.appendChild(el("line",{x1:ml,x2:ml+PW,y1:refY,y2:refY,stroke:"#7a3030","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("Pre-conflict ~$67",{x:ml+4,y:refY-3,"text-anchor":"start","font-size":"7","fill":"#7a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Area fill
  var areaFillPts=data.map(function(d,i){return xp(i)+","+yp(d.v);}).join(" ");
  var bot=mt+PH;
  svg.appendChild(el("polygon",{points:xp(0)+","+bot+" "+areaFillPts+" "+xp(n-1)+","+bot,fill:"#4a5568","fill-opacity":"0.07"}));
  // Line: pre-conflict grey, post-conflict navy, retracement muted
  for(var i=0;i<n-1;i++){
    var col=(i<9)?"#9ca3af":(i<14)?"#3a7a55":"#4a5568";
    svg.appendChild(el("line",{x1:xp(i),y1:yp(data[i].v),x2:xp(i+1),y2:yp(data[i+1].v),stroke:col,"stroke-width":"2"}));
  }
  // Event markers
  var events=[
    {i:9,label1:"Feb 28",label2:"Conflict"},
    {i:17,label1:"Apr 8",label2:"Ceasefire"}
  ];
  events.forEach(function(ev){
    var ex=xp(ev.i);
    svg.appendChild(el("line",{x1:ex,y1:mt,x2:ex,y2:mt+PH,stroke:"#1a3560","stroke-opacity":"0.4","stroke-dasharray":"2,3","stroke-width":"1"}));
    var crowded=false;
    var offset=crowded?-40:3;
    var yStart=mt+20;
    var anchor=crowded?"end":"start";
    svg.appendChild(txt(ev.label1,{x:ex+offset,y:yStart,"text-anchor":anchor,"font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    svg.appendChild(txt(ev.label2,{x:ex+offset,y:yStart+10,"text-anchor":anchor,"font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Gold pill on peak (Apr 10, index 13)
  var pillW=52,pillH=16;
  var peakX=xp(13);
  var pillX=peakX-pillW-6;
  var pillY=yp(data[13].v)-pillH/2;
  svg.appendChild(el("circle",{cx:peakX,cy:yp(data[13].v),r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(txt("$117 peak",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"8.5","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(el("line",{x1:ml,x2:ml,y1:mt,y2:mt+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  svg.appendChild(el("line",{x1:ml,x2:ml+PW,y1:mt+PH,y2:mt+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  var container=cs?cs.parentNode:null;
  if(container) container.appendChild(svg);
})();
</script>
</div>
