<div style="padding:12px 14px 8px;">
<script>
(function(){
  var cs = document.currentScript;
  // TSX sub-sector returns Feb 28 to Jun 6 2026 (approximate, sourced)
  var sectors = [
    {name:"Energy",val:34.1},
    {name:"Materials",val:18.6},
    {name:"Utilities",val:8.2},
    {name:"Industrials",val:6.4},
    {name:"Healthcare",val:5.1},
    {name:"Consumer Disc",val:2.8},
    {name:"TSX Composite",val:2.3},
    {name:"Financials",val:1.4},
    {name:"Consumer Staples",val:0.6},
    {name:"Real Estate",val:-2.1},
    {name:"Comm Services",val:-3.4},
    {name:"Technology",val:-5.8}
  ];
  // Sort descending already
  var n=sectors.length;
  var W=680,H=300,ml=110,mr=60,mt=18,mb=30;
  var PW=W-ml-mr, PH=H-mt-mb;
  var minV=-8, maxV=38;
  var bh=(PH/n)*0.65;
  function xp(v){return ml+Math.max(0,(v-minV)/(maxV-minV)*PW);}
  function xpraw(v){return ml+(v-minV)/(maxV-minV)*PW;}
  function yc(i){return mt+i*(PH/n)+PH/n/2;}
  function el(tag,attrs){
    var e=document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){var e=el("text",attrs);e.textContent=s;return e;}
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("width","100%");
  svg.style.display="block";
  // Zero line
  var zeroX=xpraw(0);
  svg.appendChild(el("line",{x1:zeroX,y1:mt,x2:zeroX,y2:mt+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  // Gridlines
  [-5,0,5,10,15,20,25,30,35].forEach(function(t){
    var x=xpraw(t);
    if(x>=ml && x<=ml+PW){
      svg.appendChild(el("line",{x1:x,y1:mt,x2:x,y2:mt+PH,stroke:"#ececec","stroke-width":"0.5"}));
      svg.appendChild(txt(t+"%",{x:x,y:mt+PH+12,"text-anchor":"middle","font-size":"7.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    }
  });
  sectors.forEach(function(s,i){
    var y=yc(i)-bh/2;
    var val=s.val;
    var barStart=xpraw(Math.min(0,val));
    var barEnd=xpraw(Math.max(0,val));
    var barW=Math.abs(barEnd-barStart);
    var col=(s.name==="TSX Composite")?"#4a5568":(val>=0?"#3a7a55":"#8a3030");
